import{_ as s,C as o,o as d,c,j as t,a,E as r,a6 as l}from"./chunks/framework.CD0vXS2f.js";const v=JSON.parse('{"title":"Full-Stack Enterprise Microsoft Foundry Platform Blueprint (v2.0)","description":"Consolidated executive white paper uniting Prompt Caching & PTU Economics, Multi-Backend APIM AI Gateway, Multi-Region BCP, and 3-Tier ACA Sandboxed Agentic RAG + 7-Layer Release Governance.","frontmatter":{"title":"Full-Stack Enterprise Microsoft Foundry Platform Blueprint (v2.0)","description":"Consolidated executive white paper uniting Prompt Caching & PTU Economics, Multi-Backend APIM AI Gateway, Multi-Region BCP, and 3-Tier ACA Sandboxed Agentic RAG + 7-Layer Release Governance."},"headers":[],"relativePath":"papers/enterprise-foundry-platform-blueprint.md","filePath":"papers/enterprise-foundry-platform-blueprint.md","lastUpdated":1795280666087}'),p={name:"papers/enterprise-foundry-platform-blueprint.md"};function u(g,e,m,y,h,f){const i=o("PlaybookMeta"),n=o("PageBrief");return d(),c("div",null,[e[0]||(e[0]=t("h1",{id:"full-stack-enterprise-microsoft-foundry-platform-blueprint-v2-0",tabindex:"-1"},[a("Full-Stack Enterprise Microsoft Foundry Platform Blueprint ("),t("code",null,"v2.0"),a(") "),t("a",{class:"header-anchor",href:"#full-stack-enterprise-microsoft-foundry-platform-blueprint-v2-0","aria-label":'Permalink to "Full-Stack Enterprise Microsoft Foundry Platform Blueprint (`v2.0`)"'},"​")],-1)),r(i,{track:"Executive Blueprint · Playbooks 01–04 Synthesis",provenance:"Customer-Zero Validated Across Regulated Enterprise Platforms",governance:"Sanitized · Peer Reviewed · IP Screened",owners:"John Luo (@jluocsa) · Co-Authors Welcome",verified:"2026-11-19 PST",status:"Live v2.0",studioHref:"/studio/",studioLabel:"Open Decision Studio →",printable:""}),r(n,{stepLabel:"EXECUTIVE REFERENCE PAPER · PRINT EDITION",readTime:"8 min read",problem:"Enterprise CTOs, CISOs, and Architecture Review Boards need one cohesive blueprint showing how capacity economics, gateway resiliency, data residency, and agent safety fit together.",takeaway:"Industrialize Microsoft Foundry across four governed seams: Pos 1–6 Prefix & Two-Regime PTU Math, SKU-Aware APIM Spillover, Residency-Symmetric DR Stamps, and MicroVM-Sandboxed Agentic Evals.",csaUse:"Click 'Print / Save as PDF' above to generate a clean executive briefing packet for customer or internal architecture sign-off."}),e[1]||(e[1]=l('<h2 id="_1-executive-summary" tabindex="-1">1. Executive Summary <a class="header-anchor" href="#_1-executive-summary" aria-label="Permalink to &quot;1. Executive Summary&quot;">​</a></h2><p>Enterprise generative AI programs rarely fail during initial proof-of-concept demos. Failures cluster at <strong>production cutover and model-upgrade waves</strong> (<code>gpt-4.x</code> / <code>o3-mini</code> → <code>gpt-5.6</code>, <code>gpt-6</code>, <code>gpt-6.1</code>), where four cross-service pressures converge simultaneously:</p><ol><li><strong>Capacity &amp; Latency Spikes (<a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/start/01-executive-thesis">Playbook 01</a>):</strong> Stateless web/container agents (<code>Model 2</code>) re-send <code>4,000–25,000+</code> system, rubric, tool, and case-context tokens on every turn. Injecting a timestamp, user ID, or unsorted tool schema near Position 1 zeroes out Azure KV prefix reuse—driving a <strong><code>2.56×</code> spike in required Provisioned Throughput (<code>170 → 435 PTUs</code>)</strong> and unamortized cache-write charges <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Burst Throttling &amp; Billing Coupling (<a href="/enterprise-azure-ai-hub/playbooks/apim-gateway/01-executive-thesis">Playbook 02</a>):</strong> Reserving year-round PTU-M for <code>4×</code> seasonal filing/close cliffs wastes <code>71%</code> of annual capacity spend, while naive gateway buffering stalls Server-Sent Events (<code>SSE</code>) and inline chargeback IDs fracture shared cache keys.</li><li><strong>Sovereignty &amp; Cold-Cache DR Surges (<a href="/enterprise-azure-ai-hub/playbooks/multi-region-bcp/01-executive-thesis">Playbook 03</a>):</strong> Regional failovers fail when spillover pools cross Data Zone boundaries, when secondary stamps choke on the <strong><code>1.8×–2.56×</code> cold-cache warm-up surge</strong> during the first 15 minutes of cutover, or when Cosmos DB and Azure AI Search lag behind.</li><li><strong>Runtime Blast Radius &amp; Flaky Evals (<a href="/enterprise-azure-ai-hub/playbooks/agentic-rag-evals/01-executive-thesis">Playbook 04</a>):</strong> Executing agent tools inside shared orchestrators creates tenant-bleed risk, while relying solely on statistical LLM-as-judge scores as PR blockers causes flaky CI pipelines.</li></ol><hr><h2 id="_2-four-layer-reference-architecture-matrix" tabindex="-1">2. Four-Layer Reference Architecture Matrix <a class="header-anchor" href="#_2-four-layer-reference-architecture-matrix" aria-label="Permalink to &quot;2. Four-Layer Reference Architecture Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Production Layer</th><th style="text-align:left;">Core Architectural Mechanism</th><th style="text-align:left;">Primary QuantitativeSLO / Outcome</th><th style="text-align:left;">Governing Standard</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Layer 01 · Context &amp; PTU Economics</strong></td><td style="text-align:left;">Strict <code>Pos 1–6</code> (<code>T0 → L2 → L1 → Volatile Tail</code>) prefix order, deterministic <code>prompt_cache_key</code> sharding (<code>N = ⌈RPM ÷ 12⌉</code>), Posture A/B ethical walls, and two-regime PTU math (<code>5.6</code> vs. <code>6</code>/<code>6.1</code>).</td><td style="text-align:left;"><code>≥80%</code> repeat cache hit rate · <code>≥10:1</code> R/W ratio · <strong><code>2.56×</code> PTU spike prevented</strong></td><td style="text-align:left;"><code>C1–C15</code> + <code>C-WP1–C-WP4</code></td></tr><tr><td style="text-align:left;"><strong>Layer 02 · APIM AI Gateway &amp; FinOps</strong></td><td style="text-align:left;">Managed Identity RBAC (<code>disableLocalAuth: true</code>), Priority-1 PTU-M + Priority-2 Standard PAYG pool with <code>Retry-After</code> circuit breaker, 5.6 breakpoint strip, <code>buffer-response=&quot;false&quot;</code> SSE, and out-of-band <code>x-cost-center</code> OTel metrics.</td><td style="text-align:left;"><strong><code>71%</code> seasonal TCO saved</strong> · <code>&lt;35ms</code> SSE TTFT delta · <code>100%</code> keyless upstream</td><td style="text-align:left;"><code>G1–G12</code></td></tr><tr><td style="text-align:left;"><strong>Layer 03 · Multi-Region BCP &amp; Residency</strong></td><td style="text-align:left;">Residency-symmetric <code>DataZone</code> / <code>Regional</code> pools, secondary PAYG quota sized <code>≥2.6×</code> steady TPM for cold-cache hydration, <code>RA-GZRS</code> ADLS + dual AI Search stamps, and multi-region Cosmos DB thread state.</td><td style="text-align:left;"><strong><code>&lt;15s</code> gateway cutover RTO</strong> · <code>0</code> residency boundary leaks · Quarterly Game-Day pass</td><td style="text-align:left;"><code>B1–B12</code></td></tr><tr><td style="text-align:left;"><strong>Layer 04 · Sandboxed Agents &amp; Evals</strong></td><td style="text-align:left;">SDK-free orchestrator proxying <code>AG-UI</code> SSE from microVM-isolated ACA Dynamic Sessions (Git-SHA tagged), Content Understanding Markdown ingestion, Foundry IQ MCP retrieval, and deterministic CI contract gates (<code>ARG001–005</code>).</td><td style="text-align:left;"><code>100%</code> microVM session isolation · <code>100%</code> resolved citation IDs · <code>0</code> flaky PR blocks</td><td style="text-align:left;"><code>A1–A12</code></td></tr></tbody></table><hr><h2 id="_3-two-regime-ptu-sizing-summary-gpt-5-6-vs-gpt-6-6-1-m" tabindex="-1">3. Two-Regime PTU Sizing Summary (<code>GPT-5.6</code> vs. <code>GPT-6 / 6.1</code>) <code>[M]</code> <a class="header-anchor" href="#_3-two-regime-ptu-sizing-summary-gpt-5-6-vs-gpt-6-6-1-m" aria-label="Permalink to &quot;3. Two-Regime PTU Sizing Summary (`GPT-5.6` vs. `GPT-6 / 6.1`) `[M]`&quot;">​</a></h2><p>Always verify target model generation before reserving Provisioned Throughput (<code>PTU-M</code>):</p><ul><li><strong>Regime 1 — Pre-GPT-6 (<code>gpt-5.6-terra</code>, <code>gpt-5.6-sol</code>, <code>gpt-5.6-luna</code>):</strong><ul><li>Cached input tokens deduct <strong><code>100%</code> (<code>0.0x</code> weight)</strong> from PTU utilization; uncached input = <code>1.0x</code>; output = <code>6.0x</code> <span class="ev-badge ev-m">[M]</span>.</li><li>Explicit <code>prompt_cache_breakpoint</code> and <code>prompt_cache_options</code> are <strong>not supported on PTU-M</strong>—strip them at the APIM gateway on the PTU leg while preserving Pos 1–6 ordering and <code>prompt_cache_key</code> <span class="ev-badge ev-m">[M]</span>.</li></ul></li><li><strong>Regime 2 — GPT-6 &amp; GPT-6.1 (<code>gpt-6-astra</code>, <code>gpt-6-sol</code>, <code>gpt-6-luna</code>, <code>gpt-6.1-sol</code>):</strong><ul><li>Explicit breakpoints are <strong>supported on PTU-M</strong> <span class="ev-badge ev-m">[M]</span>.</li><li>Normalized token weights apply: ordinary input = <code>1.0x</code>, cached read = <code>0.10x</code> (<code>0.05x</code> on <code>gpt-6.1-sol</code>), cache write = <code>1.25x</code>, output = <code>5.0x</code> <span class="ev-badge ev-m">[M]</span>.</li><li>Steady-state cached hit fraction is bounded by <code>k / (k + 1)</code> at Read/Write ratio <code>k:1</code> (<code>≥10:1</code> recommended so write overhead stays <code>&lt;3%</code>).</li></ul></li></ul><hr><h2 id="_4-turnkey-3-week-enterprise-readiness-engagement" tabindex="-1">4. Turnkey 3-Week Enterprise Readiness Engagement <a class="header-anchor" href="#_4-turnkey-3-week-enterprise-readiness-engagement" aria-label="Permalink to &quot;4. Turnkey 3-Week Enterprise Readiness Engagement&quot;">​</a></h2><ol><li><strong>Intake (30 Minutes):</strong> Score workload boundaries in the <a href="/enterprise-azure-ai-hub/studio/#triage">Interactive Decision Studio</a> to select activated tracks and size initial PTU/BCP envelopes.</li><li><strong>Week 1 — Baseline &amp; Static Audit:</strong> Run <code>pcr_lint.py</code> across application repos, capture 24-hour un-tuned App Insights baselines, and verify regional SKU/quota parity.</li><li><strong>Week 2 — Middleware, Gateway &amp; Sandbox Refactor:</strong> Reorder prompts to <code>Pos 1–6</code>, deploy <code>apim-foundry-spillover-policy.xml</code>, wire Foundry IQ MCP + Content Understanding, and enforce Git-SHA ACA session tags.</li><li><strong>Week 3 — Load, Game-Day &amp; 52-Gate Sign-Off:</strong> Execute peak concurrency tests, run a 30-minute regional <code>429</code>/<code>503</code> Game-Day failover drill, enforce <code>agent_release_gate.py</code> in CI, and sign off the applicable <a href="/enterprise-azure-ai-hub/papers/migration-readiness-checklist"><code>C</code> / <code>G</code> / <code>B</code> / <code>A</code> Readiness Checklists</a>.</li></ol>',13))])}const b=s(p,[["render",u]]);export{v as __pageData,b as default};
